from pathlib import Path
import json,subprocess,datetime,hashlib,shutil
r=Path('C:/.projects/venus');out=r/'.artifacts/p05-a13-owned-cpu-profile01';d=json.loads((out/'cpu-profile.json').read_text());assert d['requested_profile_ms']==7000
before=json.loads((out/'inspect-before.json').read_text());after=json.loads((out/'inspect-after.json').read_text());assert before==after;cid=before['id'];project=before['project']
js=r"import fs from'node:fs';const listeners=p=>fs.readFileSync(p,'utf8').split('\n').map(x=>x.trim().split(/\s+/)).filter(x=>x[3]==='0A'&&x[1]?.endsWith(':240D')).map(x=>x[1]);console.log(JSON.stringify({tcp:listeners('/proc/net/tcp'),tcp6:listeners('/proc/net/tcp6')}));"
p=subprocess.run(['docker','exec',cid,'node','--input-type=module','-e',js],capture_output=True,text=True,encoding='utf-8',timeout=30);assert p.returncode==0,p.stderr;(out/'listener-after03.json').write_text(p.stdout,encoding='utf-8');assert json.loads(p.stdout)=={'tcp':['0100007F:240D'],'tcp6':[]}
shutil.copyfile(r/'.artifacts/p05-a11-owned-cpu-profile01/aggregate.py',out/'aggregate.py');q=subprocess.run([str(r/'.venv/Scripts/python.exe'),'-X','utf8','-B',str(out/'aggregate.py')],cwd=r,capture_output=True,text=True);assert q.returncode==0,q.stderr
(out/'receipt03.json').write_text(json.dumps({'created_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'ONE_OWNED_7S_CPU_PROFILE_CAPTURED_NOT_FUNCTIONAL_OR_LATENCY_PASS','capture_exit':0,'aggregate_exit':q.returncode,'project':project,'image':before['image'],'source_identity':'5be635651557399fb9ef865ebd17c813fdf0c0eda8fc96f76a3840894cef039a','unchanged_prior_capture_sha256':hashlib.sha256((out/'capture.mjs').read_bytes()).hexdigest(),'instrumented_cohort':'in_person/questions','normal_uninstrumented_cohort_acceptance':False,'private_payload_or_heap':False,'listener_cleanup':'EXISTING_PARENT_COHORT_COMPOSE_TEARDOWN','wrapper01_exit':1,'wrapper01_failure':'POST_CAPTURE_LISTENER_CHECK_MATCHED_CONNECTION_ROWS_ALSO_NOT_NATIVE_CAPTURE_FAILURE','finalize02_exit':1,'finalize02_failure':'POST_CAPTURE_LISTENER_CHECK_DID_NOT_FILTER_LISTEN_STATE','capture_repeated':False},indent=2)+'\n',encoding='utf-8');a=json.loads((out/'AGGREGATES.json').read_text());print(json.dumps({'capture_exit':0,'profile_ms':a['profile_elapsed_ms'],'top_self':a['top_self'][:7],'top_inclusive':a['top_inclusive'][:6]}))
